INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('bg_tunnel_crawl', 'environment', 'background', 'Sprites/Backgrounds/bg_tunnel_crawl', 1920, 600, 1, 1, 'Bilinear', NULL, 'dark fantasy, ink-and-gold illustration style, dramatic rim lighting, muted palette, no text, no watermark, no characters, no UI. Wide cinematic panorama. Narrow underground tunnel seen from a low crawl perspective; rough-hewn stone walls pressing close; pitch black ahead; faint crack of light at far end; debris and dust on floor; no lava or monsters; oppressive claustrophobic geometry; palette: near-black stone, warm amber crack of light, cold grey dust.')
