INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('bg_umbracleft', 'environment', 'background', 'Sprites/Backgrounds/bg_umbracleft', 1920, 1080, 1, 100, 'Bilinear', '#1A1040', 'dark fantasy, ink-and-gold illustration style, dramatic rim lighting, muted palette, no text, no watermark, no characters, no UI. Wide cinematic panorama, low horizon, clear foreground ground plane. Underground Shadowdeep cavern battlefield: deep blue-black basalt stone chamber with towering walls; jagged void tears split the cavern walls like vertical rifts, leaking faint electric-violet glow (subtle, not neon); crystalline shadow formations jut from the floor and walls like obsidian geodes, catching cold highlights; flickering torchlight from iron sconces creates warm amber pools and long oppressive shadows; thin ground fog and drifting ash motes for depth; oppressive darkness swallowing the far background. Palette: blue-black stone, charcoal, cold slate, muted violet accents, warm ember-amber torchlight. Negative prompts: no modern objects, no lava rivers, no bright cyan, no purple haze everywhere, no characters, no logos, no readable symbols.')
