INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('ui_loading_screen', 'ui', 'background', 'Assets/Art/UI/Screens/loading_screen', 1920, 1080, 1, 100, 'Bilinear', '#7C4DFF', 'Loading screen. Lone mercenary silhouetted against a massive swirling void rift in a vast underground cavern. Ink-and-gold illustration style, dramatic rim lighting, muted palette with electric violet void energy and ember-gold torchlight. Ancient stone columns with glowing runes frame the edges. Volumetric fog, ash particles floating upward. Heavy ink linework, weathered textures, cinematic composition with figure small against immense rift. No text, no watermark, no UI.')
