INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('class_cleric', 'class', 'icon', 'Sprites/Icons/class_cleric', 32, 32, 1, 32, 'Point', '#F0DC5A', 'Pixel art class icon, 32x32, transparent background. Mercenary cleric silhouette in mail with a tabard — bold, centered, instantly readable at 1x size. Holds a holy symbol aloft (clear beacon/standard shape) with a “Morale Officer” support-leader vibe. 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (highlight/mid/shadow), minimal internal detail (no noisy texture). Grimdark low-fantasy materials: worn mail texture implied with a few pixel clusters, weathered cloth tabard, dull steel mace/sidearm optional but secondary. Subtle gold accent glow (controlled, no blur; keep edges crisp), used only on the holy symbol and/or trim. No text, no watermark, no UI frame.

hold the mace correctly.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
