INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('class_druid', 'class', 'icon', 'Sprites/Icons/class_druid', 32, 32, 1, 32, 'Point', '#5AD25A', 'Pixel art class icon, 32x32, transparent background. Mercenary druid silhouette (“Thornwarden”) — bold, centered, instantly readable at 1x size. Holds a gnarled staff with vine growth (clear vine silhouette wrapping the staff), with rugged nature gear hints (cloak/pauldron shape) kept secondary. 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (highlight/mid/shadow), minimal internal detail (no noisy texture). Grimdark low-fantasy materials: worn leather/cloth, rough wood staff, thorny vine forms. Subtle forest green accent glow (controlled, no blur; keep edges crisp), used only on the vine growth and/or small rune mark. No text, no watermark, no UI frame.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
