INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('compass_apostate', 'misc', 'icon', 'Sprites/Icons/compass_apostate', 16, 16, 1, 16, 'Point', '#604040', 'Pixel art compass state icon, 16x16, transparent background. “Rejected by both factions” symbol: a broken Crown stamp above a torn Void mark (rift tear) — compact, centered, instantly readable at 1x size. Grey, desaturated base with a single sharp red crack slash running through both symbols (clear diagonal break). 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (light grey highlight, mid grey fill, near-black shadow); minimal internal detail (no texture noise). Subtle red glow limited to the crack only (no blur; keep edges crisp). No text, no watermark, no UI frame.')
