INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('compass_blackhandagent', 'misc', 'icon', 'Sprites/Icons/compass_blackhandagent', 16, 16, 1, 16, 'Point', '#200010', 'Pixel art compass state icon, 16x16, transparent background. Black Hand aligned “secret” state symbol: a Black Hand brand mark (stylized palm print) — compact, centered, instantly readable at 1x size. Palette: dark red-black base (near-black #0C0C14 with deep crimson fill accents), with a subtle branded/burnt stamp look. 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (dark highlight, mid crimson fill, near-black shadow); minimal internal detail (no texture noise). Optional: a tiny crimson ember edge on fingertips to suggest void-taint (controlled, no blur; keep edges crisp). No text, no watermark, no UI frame.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
