INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('compass_greyoperator', 'misc', 'icon', 'Sprites/Icons/compass_greyoperator', 16, 16, 1, 16, 'Point', '#707080', 'Pixel art compass state icon, 16x16, transparent background. “Balanced / both axes elevated” symbol: a split circle coin-disc, left half Crown gold and right half Void shadow, clean 50/50 division. Add a small “raised” cue: a thin grey ring/halo behind the disc or a tiny upward chevron at top (keep it simple and readable at 1x). Palette: neutral grey base with muted gold on one half and muted void-violet/near-black on the other (no neon). 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (light grey highlight, mid grey fill, near-black shadow); minimal internal detail (no texture noise). Optional: tiny gold glint on the gold half and tiny violet pin-prick on the void half (controlled, no blur; edges crisp). No text, no watermark, no UI frame.')
