INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('compass_riftwrought', 'misc', 'icon', 'Sprites/Icons/compass_riftwrought', 16, 16, 1, 16, 'Point', '#4A1FA8', 'Pixel art compass state icon, 16x16, transparent background. “Riftwrought / default path (no allegiances)” symbol: a void-shaped marker (teardrop/needle marker silhouette) with an inner rift slit, compact and centered, instantly readable at 1x size. Palette: dark purple-black (near-black #0C0C14 base with muted deep violet fill), no neon. 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed. Three clear contrast tiers (dim violet highlight, mid deep-violet fill, near-black shadow); minimal internal detail (no texture noise). Optional: 1–2 pixel violet “spark” at the rift slit tip to imply void energy (controlled, no blur; keep edges crisp). No text, no watermark, no UI frame.')
