INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('icon_bandage', 'misc', 'icon', 'Sprites/Icons/icon_bandage', 32, 32, 1, 16, 'Point', NULL, 'Pixel art rolled bandage icon, 32x32. Bright cream outer rim, recessed dark groove, mid-tone linen spiral center with near-black spiral line detail. Three clear contrast tiers. Hard pixel edges throughout, no anti-aliasing, no white highlights. Clean transparent background with zero alpha bleed. Grimdark low-fantasy RPG style.')
