INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('relic_liquidators_lens', 'relic', 'icon', 'Sprites/Icons/Relics/relic_liquidators_lens', 64, 64, 1, 16, 'Point', '#32C882', 'Dark fantasy Void Ledger relic icon, flat illustration, transparent background, readable at 64px, ink linework, centered composition, high silhouette clarity. Subject: a monocle (corrupted accounting artifact) with a fractured lens; through the main crack, a void “eye” is visible staring back.

