INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('upgrade_chapel', 'misc', 'node', 'Sprites/UI/upgrade_chapel', 24, 24, 1, 24, 'Point', NULL, 'Pixel art UI icon, 32x32, transparent background. Subject: chapel symbol — gothic arch window with holy light. Centered, instantly readable at 1x size.

Design:

- Tall pointed gothic arch window silhouette (single window), with 1–2 simple mullion bars (a cross or vertical split), kept chunky
- Inner “holy light” shining through: bright warm core inside the window with 1–2 stepped rays spilling downward/outward (minimal, readable)
- Optional: tiny stained-glass hint using 2–3 pixels of muted color blocks inside the window (very subtle; don’t clutter)

Rendering rules:

- 1px near-black outline (#0C0C14), hard pixel edges, no anti-aliasing, zero alpha bleed
- Three clear contrast tiers (highlight / midtone / shadow), minimal texture (no dithering noise)
- Stone frame: dark grey/near-black with a few lighter edge highlights
- Holy light: warm ivory/gold with pixel-stepped glow only (tight 1–2 px halo, no blur/bloom)

Negative prompts: no background scenery, no UI frame, no text, no watermark.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
