INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('node_codex', 'node', 'node', 'Assets/Sprites/Nodes/node_codex', 24, 24, 1, 24, 'Point', NULL, 'Pixel art node map icon for the Codex NPC encounter room. Transparent background, hard pixel edges, no anti-aliasing. Square tile with rounded outer corners matching existing node icons. Background fill: deep void-black #05020C with subtle inner vignette. Icon motif: an open book or stone tablet with a single all-seeing eye above it — stylized, geometric, not realistic. The eye represents the Codex as observer/recorder. Eye iris: electric violet #7C4DFF with 1px bright-white #E8E0FF specular dot. Book/tablet: muted dusty-white #C8C3D2 pages with 3–4 horizontal line marks. Outer ring: 1px #7C4DFF violet border. Subtle 1px inner glow in violet on the eye only. Mysterious, archival, slightly unsettling. NEGATIVE: No warm tones, no gold, no orange. No star or magic wand. Eye and book must both read clearly at small size.')
