INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('node_shrine', 'node', 'node', 'Sprites/Nodes/node_shrine', 48, 48, 1, 24, 'Point', NULL, 'Dark fantasy RPG node icon, flat illustration, transparent background, readable at 48px, ink linework. Subject: lit candle on a small stone altar; holy glow.

Composition:

- Centered icon, high silhouette clarity at 48px
- Simple altar block (rectangular stone slab) with a small raised base
- Single tall candle on top, flame clearly visible; a few wax drips down the side (minimal)

Style + lighting:

- Clean ink linework with sparse crosshatching (keep lines bold enough to read small)
- Limited flat shading (2–3 values max), avoid painterly texture
- Holy glow: warm gold/ivory halo around the flame and upper candle only (tight, controlled glow; no large bloom)
- Optional: faint radiant “ray ticks” (3–6 short strokes) above the flame to signal sanctity (abstract, not text)

Constraints:

- Transparent background
- No text, no watermark
- Keep negative space around the silhouette; avoid extra props (no books, skulls, etc.)')
