INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('node_vault', 'node', 'node', 'Assets/Sprites/Nodes/node_vault', 24, 24, 1, 24, 'Point', NULL, 'Pixel art node map icon for the Vault / Debt Cache room (post-boss blind reward). Transparent background, hard pixel edges, no anti-aliasing. Square tile with rounded outer corners. Background fill: deep near-black #0A080F. Icon motif: a heavy iron vault door or strongbox, slightly ajar, with void-light leaking from the gap. Vault door: dark iron grey #2A2A38, highlight rim #4A4860 on top-left edges 1px. Void-light leak: electric violet #7C4DFF to near-white #D0C8F0 at center, 3–4px width. Locking bolt or wheel: small circular handle #5A4080 with 1px highlight. Outer border: gold-amber #D4AA32 1px ring — reward node. NEGATIVE: Not a treasure chest. No coins spilling out. No skull/bones.')
