INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('portrait_boss_furnace_warden', 'creature', 'portrait', 'Assets/Sprites/Portraits/portrait_boss_furnace_warden', 48, 64, 1, 32, 'Point', NULL, 'Pixel art bust portrait of The Furnace Warden, Tier 3 anchor boss of Brimstone Bastions biome. Hard edges, no anti-aliasing, transparent background. 3/4 angle facing left. Heavily armored being fused to furnace architecture — armor merged with furnace metal, chains, and burned contract documents on breastplate. Helmet: full-face iron helmet with visor glowing like furnace interior orange-white #FFA040. Chest: thick forge-iron armor #1A1210 with burn-orange highlights #C85020 at raised edges, incinerated contract text as darker marks. Shoulders: heavy pauldrons with small chimney protrusions venting heat (2–3px red-orange wisps). 1px chain detail #5A4020 on foreground shoulder. Primary palette: deep ember-red #800C00, furnace-orange #C84010, forge-gold #D08020, charred black #0C0805. 1px near-black outline. NEGATIVE: No actual fire — heat is implied. Not demonic, no horns, no wings — industrial constructed warden.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('portrait_boss_invisible_hand', 'creature', 'portrait', 'Assets/Sprites/Portraits/portrait_boss_invisible_hand', 48, 64, 1, 32, 'Point', NULL, 'Pixel art bust portrait of The Invisible Hand, Tier 4 final boss of Ledgerwell. Hard edges, no anti-aliasing, transparent background. 3/4 angle facing left. Formally dressed figure in a perfectly tailored dark void-suit (bureaucrat, not warrior), impossibly still. One arm extends slightly, gloved in white #E8E8F8 fading into translucency — arm partially absent. Face: perfectly smooth dark oval with only a single ledger-line across where mouth should be — flat ruled line. Head slightly oversized, subtly wrong proportions (void distortion). Monocle-lens gold-rimmed #B09040 over eye area with no eye behind it — just void. Faint ruled ledger lines #101830 radiating outward behind figure. Tiny Black Hand brand mark #3A1A60 on left lapel. Primary palette: void-black #05020C, electric violet #7C4DFF, cold ledger-white #E8E8F8, deep audit-blue #0A1840. 1px near-black outline. NEGATIVE: No visible weapon. Not horrific — unsettling through uncanny corporate perfection. No floating debris or dramatic magic — stillness is the threat.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('portrait_boss_prologue', 'creature', 'portrait', 'Assets/Sprites/Portraits/portrait_boss_prologue', 48, 64, 1, 32, 'Point', NULL, 'Pixel art bust portrait of The Hollow Foreman, prologue rift boss. Hard edges, no anti-aliasing, transparent background. Bust/chest portrait, 3/4 angle facing left. A low-tier Umbracleft shadow construct — humanoid figure assembled from compressed void-darkness, wearing remnants of an old guild foreman''s coat over a body that isn''t quite solid. Primary palette: deep shadow-purples #1A0A2A, #2A1040, void-black #05020C. Coat: tattered dark charcoal #1E1C28 with frayed edges dissolving into shadow. Face: hollow — two dim ember-orange pinpoints #C85020 where eyes should be. Silhouette: mostly solid top-left, dissolving into smoke/wisps on right side. Guild emblem on coat barely visible, scratched-out. Faint violet mist #3A1A5A in top corners only. 1px near-black outline. NEGATIVE: Not skeletal, not a ghost. No crown or elaborate headwear — Tier 0.5 boss.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('portrait_boss_rot_king', 'creature', 'portrait', 'Assets/Sprites/Portraits/portrait_boss_rot_king', 48, 64, 1, 32, 'Point', NULL, 'Pixel art bust portrait of The Rot-King, Tier 2 anchor boss of Rot-King Reliquary biome. Hard edges, no anti-aliasing, transparent background. 3/4 angle facing left. A massive decaying humanoid wearing a corroded crown fused to its skull — crown partially buried in rot, tilted. Skin: mottled dark-green-brown with visible fissures leaking yellow-green plague light #B0CC40 at 1px cracks. Eyes: clouded white #D0D0A0 with no pupil — plague blindness. Chest: remnants of tattered royal robes dark maroon #3A1020 under decay layers. 1–2 fungal growths on shoulder, small #6A8020 mushroom caps. Primary palette: sickly bile-green #3A6010, plague-yellow #8AAA20, necrotic brown #2A1A08. Sickly green-yellow mist background. 1px near-black outline. NEGATIVE: Not purely skeletal — still rotting flesh. No bright red blood. Crown must read as a crown.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('portrait_boss_umbral_sovereign', 'creature', 'portrait', 'Assets/Sprites/Portraits/portrait_boss_umbral_sovereign', 48, 64, 1, 32, 'Point', NULL, 'Pixel art bust portrait of The Umbral Sovereign, Tier 1 anchor boss of Umbracleft biome. Hard edges, no anti-aliasing, transparent background. 3/4 angle facing left. A tall regal void-being with a crown of crystallized shadow — sharp asymmetrical shards of compressed void (not metal, not bone). Face: smooth featureless except single vertical split emitting cold light #A080FF. Shoulders: cape/mantle of living shadow with loose fringe pixels suggesting motion. Chest armor: void-plate dark violet-black #140828 with violet trim #5030A0 at seams. Primary palette: electric violet #7C4DFF, deep void-black #05020C, cold indigo #1A0A3A. Cold violet mist background haze. 1px near-black outline. NEGATIVE: No warm colors anywhere. Crown should feel earned and regal, not comedic.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
