INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('ui_gear_rarity_charter', 'ui', 'ui', 'Sprites/UI/Chrome/ui_gear_rarity_charter', 8, 192, 1, 1, 'Bilinear', '#44BB44', 'Pixel art UI element (rarity stripe), 8x192, transparent background. Narrow vertical rarity stripe for gear cards — Charter/Uncommon tier. Hard pixel edges, no anti-aliasing, zero alpha bleed. Design: a slim vertical bar with a slightly brighter green inner core and darker green outer edge, plus a subtle “glow” achieved via 1–2 pixel stepped highlight along one side (no blur, no gradients). Add 2–3 small notch marks or tiny corner ticks spaced vertically to suggest “crafted/charter” without readable symbols. Palette: muted forest green base + brighter emerald highlight + near-black (#0C0C14) shadow pixels for contrast. No text, no watermark.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('ui_gear_rarity_common', 'ui', 'ui', 'Sprites/UI/Chrome/ui_gear_rarity_common', 8, 192, 1, 1, 'Bilinear', '#AAAAAA', 'Pixel art UI element (rarity stripe), 8x192, transparent background. Narrow vertical rarity stripe for gear cards — Common tier. Hard pixel edges, no anti-aliasing, zero alpha bleed. 9-slice friendly: keep the top and bottom 4–6 px clean and symmetrical; make the middle section vertically tileable (no unique marks in the center that would break tiling).

Design: flat grey-white stripe with very subtle depth (no gradients) using stepped pixels only:

- Outer edge: near-black (#0C0C14) 1px outline (optional if your cards already have a frame)
- Inner border: darker grey edge pixels
- Core: light grey-white fill (mostly flat)

Add at most 1–2 tiny neutral “wear” nicks near the top and bottom only (keep minimal; no texture noise).

No text, no watermark.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
  ppu = EXCLUDED.ppu, filter_mode = EXCLUDED.filter_mode,
  primary_color = COALESCE(EXCLUDED.primary_color, public.sprite_assets.primary_color),
  prompt_template = EXCLUDED.prompt_template;

INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('ui_gear_rarity_crown', 'ui', 'ui', 'Sprites/UI/Chrome/ui_gear_rarity_crown', 8, 192, 1, 1, 'Bilinear', '#4488FF', 'Pixel art UI element (rarity stripe), 8x192, transparent background. Narrow vertical rarity stripe for gear cards — Crown/Rare tier. Hard pixel edges, no anti-aliasing, zero alpha bleed. 9-slice friendly: keep the top and bottom 4–6 px clean and symmetrical; make the middle section vertically tileable (no unique marks in the center that would break tiling).

Design: deep blue core stripe with a crisp stepped glow (no blur/gradient):

- Optional 1px near-black outline (#0C0C14) if needed for separation from the card
- Inner border: dark navy pixels
- Core: rich royal blue fill (mostly flat)
- Glow: 1–2 px “aura” on the outer side(s) using 2–3 stepped shades (navy → blue → pale ice-blue highlights), kept tight and pixel-stepped (no soft bloom)

Add 1–2 tiny crown-like notch ticks near the top only (abstract, not readable as text), keep minimal.

No text, no watermark.')
ON CONFLICT (asset_key) DO UPDATE SET
  category = EXCLUDED.category, tier = EXCLUDED.tier, unity_path = EXCLUDED.unity_path,
  target_w = EXCLUDED.target_w, target_h = EXCLUDED.target_h, frame_count = EXCLUDED.frame_count,
