INSERT INTO public.sprite_assets (asset_key, category, tier, unity_path, target_w, target_h, frame_count, ppu, filter_mode, primary_color, prompt_template) VALUES ('ui_guildhall_callout_accent', 'ui_chrome', 'ui', 'Assets/Sprites/UI/GuildHall/ui_guildhall_callout_accent.png', 96, 8, 1, 8, 'Point', NULL, 'Opening: Thin horizontal accent bar for callout sections in a dark fantasy guild hall UI. Used as a decorative divider.
Design: A narrow horizontal bar (96x8px) with a subtle center diamond or notch motif. The bar itself is 2px tall with 1px border, centered vertically. Ends taper to single-pixel points.
Rendering: Pixel art, perfectly horizontal, tileable by repeating the center section. The center diamond/notch should be the only non-repeating element.
Palette: Dull gold (#8B7642) bar, near-black outline, single brighter accent pixel at center diamond.
Negative: No vertical elements, no glow, no smoke, no gradient, no thick borders.')
